#pragma once

#include <SFML/Graphics.hpp>
#include <string>
#include <vector>

namespace Fem
{

// One span of text with one style. A run never contains a newline generated by
// wrapping; line breaks stay inside the run and are handled by sf::Text.
struct TextStyle
{
    sf::Color color = sf::Color::White;
    bool bold = false;
    bool italic = false;
    bool underline = false;
    bool strike = false;
    unsigned size = 0;  // 0 = inherit the command's text size
    std::string fontId; // empty = inherit the command's font

    bool operator==(const TextStyle& other) const
    {
        return color.r == other.color.r && color.g == other.color.g && color.b == other.color.b &&
               color.a == other.color.a && bold == other.bold && italic == other.italic &&
               underline == other.underline && strike == other.strike && size == other.size && fontId == other.fontId;
    }
    bool operator!=(const TextStyle& other) const
    {
        return !(*this == other);
    }
};

struct TextRun
{
    std::string text;
    TextStyle style;
};

struct RichText
{
    std::vector<TextRun> runs;
    std::string plain;
    bool hasMarkup = false;
};

// Parses a compact markup used by UI labels:
//
//   {b}bold{/b} {i}italic{/i} {u}under{/u} {s}strike{/s}
//   {color=#ff8800}orange{/color}
//   {size=24}larger{/size}
//   {font=title}another face{/font}
//   {{ and }} produce literal braces
//
// Unknown tags are preserved verbatim, which keeps a translation containing
// braces from silently losing text. Styles nest; {reset} returns to the base
// style. `base` supplies the command's colour/size/font.
RichText ParseRichText(const std::string& source, const TextStyle& base);

// Parses and concatenates only the text (used by accessibility, localization
// QA and measuring).
std::string StripRichText(const std::string& source);

// True when the text contains a tag this parser understands. Cheap enough for
// a UI frame; callers use it to choose the plain-text fast path.
bool HasRichTextMarkup(const std::string& source);

} // namespace Fem
